<?php

declare(strict_types=1);

# @autogenerated

namespace Civi\Lughauth\Features\Oidc\Par\Application\Usecase\ResolveParRequest;

use Civi\Lughauth\Features\Oidc\Par\Domain\Gateway\ParRequestGateway;
use Civi\Lughauth\Features\Oidc\Par\Domain\ParRequest;
use Civi\Lughauth\Features\Oidc\Par\Domain\Exception\ParException;

final class ResolveParRequestUsecase
{
    public function __construct(
        private readonly ParRequestGateway $gateway,
    ) {
    }

    public function resolve(string $requestUri, string $tenant): ParRequest
    {
        $parRequest = $this->gateway->findByUri($requestUri, $tenant);

        if ($parRequest === null) {
            throw ParException::invalidRequestUri();
        }
        if ($parRequest->isUsed()) {
            throw ParException::invalidRequestUri();
        }
        if ($parRequest->isExpired()) {
            throw ParException::invalidRequestUri();
        }

        $this->gateway->markUsed($requestUri, $tenant);

        return $parRequest;
    }
}
